insert into switch_device (id, device_name, device_number, device_type, device_subtype, voltage_class, default_operation, description, location, group_name, created_at) values
  ('40000000-0000-0000-0000-000000000600', 'LBS-101', '441-E-SW-101', 'DS', 'LBS', '22.9kV', '개방', '호포변전소측 수전선로 부하개폐기(24kV,630A,12.5kA). 도면 직접 확인.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000601', 'ES-101', '441-E-SW-101', 'ES', null, '22.9kV', '투입', 'LBS-101측 접지개폐기(25.8kV,25kA) — 점검 시 투입하여 접지상태 확보.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000602', 'LBS-201', '441-E-SW-201', 'DS', 'LBS', '22.9kV', '개방', '노포변전소측 수전선로 부하개폐기(24kV,630A,12.5kA, 예비선로). 도면 직접 확인.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000603', 'ES-201', '441-E-SW-201', 'ES', null, '22.9kV', '투입', 'LBS-201측 접지개폐기(25.8kV,25kA) — 점검 시 투입하여 접지상태 확보.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000604', 'VCB-101', '441-E-SW-103', 'CB', 'VCB', '22.9kV', '개방', '#1(호포) 22.9kV 수전 INCOMING 차단기(24kV,1250A,25kA, 상시 투입=N.C). 도면상 VCB-201과 INTERLOCK 점선 직결(상호 배타) 직접 확인.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000605', 'VCB-201', '441-E-SW-203', 'CB', 'VCB', '22.9kV', '개방', '#2(노포) 22.9kV 수전 INCOMING 차단기(24kV,1250A,25kA, 상시 개방=N.O 예비선로). VCB-101과 상호 인터록(동시투입 금지) — 도면 직접 확인.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000606', 'VCB-102', '441-E-SW-106', 'CB', 'VCB', '22.9kV', '개방', 'LOAD CENTER TR#1(MTR-01) 급전 차단기(24kV,1250A,25kA, 상시 투입=N.C). VCB-202와 INTERLOCK 직결 확인.', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000607', 'VCB-202', '441-E-SW-204', 'CB', 'VCB', '22.9kV', '개방', 'LOAD CENTER TR#2(MTR-02) 급전 차단기(24kV,1250A,25kA, 상시 개방=N.O 예비). VCB-102와 상호 인터록 확인. ⚠️Tag대장상 태그는 "SW-202"로 기재되어 있으나 참조파일 문서번호는 441-E-SW-204 — SW-202는 PT(441-E-SW-202)의 패널태그와 동일해 혼용된 것으로 보임(확인 필요, 두 소스 모두 VCB-202 자체를 가리키는 건 확실함).', '사송가압장 2층 전기실', null, now()),
  ('40000000-0000-0000-0000-000000000608', 'LC-1_ACB-101', '443-E-LC-101', 'CB', 'ACB', '460V', '개방', 'LOAD CENTER TR#1(MTR-01) 2차측 INCOMING(690V,1600AF/1600AT, N.C). 도면 직접 확인.', '사송가압장 2층 전기실', 'LC-1', now()),
  ('40000000-0000-0000-0000-000000000609', 'LC-2_ACB-201', '443-E-LC-201', 'CB', 'ACB', '460V', '개방', 'LOAD CENTER TR#2(MTR-02) 2차측 INCOMING(690V,1600AF/1600AT, N.O 예비 — 평상시 TIE(ACB-106)를 통해 LC-101에서 받는 것으로 판단). 도면 직접 확인.', '사송가압장 2층 전기실', 'LC-2', now()),
  ('40000000-0000-0000-0000-00000000060a', 'LC-1_ACB-106', '443-E-LC-106', 'CB', 'ACB', '460V', '개방', 'L/C#1↔#2 BUS TIE(690V,1600AF/1600AT, N.C). 도면 NOTE: "BUS TIE BREAKER IS KEY INTERLOCKED WITH TWO INCOMING BREAKERS"(ACB-101/ACB-201) 직접 확인.', '사송가압장 2층 전기실', 'LC-1', now()),
  ('40000000-0000-0000-0000-00000000060b', 'LC-1_ACB-102', '443-E-LC-102', 'CB', 'ACB', '460V', '개방', '460V MCC#1 급전 피더(690V,630AF/630AT). 도면 직접 확인.', '사송가압장 2층 전기실', 'LC-1', now()),
  ('40000000-0000-0000-0000-00000000060c', 'LC-2_ACB-202', '443-E-LC-202', 'CB', 'ACB', '460V', '개방', '460V MCC#2 급전 피더(690V,630AF/630AT). 도면 직접 확인.', '사송가압장 2층 전기실', 'LC-2', now()),
