insert into interlock (source_equipment_id, target_equipment_id, interlock_type, description) values
  ('30000000-0000-0000-0000-000000000604', '30000000-0000-0000-0000-000000000609', '상호 인터록(정상/예비 배타)', '22.9kV 수전 INCOMING — VCB-101(N.C,정상,호포)·VCB-201(N.O,예비,노포)이 도면상 INTERLOCK 점선으로 직결되어 동시투입 금지. 한쪽 작업 전 반드시 반대쪽 실제 투입 상태를 확인할 것.'),
  ('30000000-0000-0000-0000-00000000060c', '30000000-0000-0000-0000-00000000060d', '상호 인터록(정상/예비 배타)', 'LOAD CENTER TR 급전 — VCB-102(N.C,정상,MTR-01)·VCB-202(N.O,예비,MTR-02)이 도면상 INTERLOCK 점선으로 직결되어 동시투입 금지.'),
  ('30000000-0000-0000-0000-000000000612', '30000000-0000-0000-0000-000000000610', '상호 인터록(KEY, TIE-인입 배타)', '도면 NOTE "BUS TIE BREAKER IS KEY INTERLOCKED WITH TWO INCOMING BREAKERS" 직접 확인 — LC-106(TIE)과 ACB-101(LC-101 인입)이 키 인터록으로 동시투입 금지.'),
  ('30000000-0000-0000-0000-000000000612', '30000000-0000-0000-0000-000000000611', '상호 인터록(KEY, TIE-인입 배타)', '도면 NOTE "BUS TIE BREAKER IS KEY INTERLOCKED WITH TWO INCOMING BREAKERS" 직접 확인 — LC-106(TIE)과 ACB-201(LC-201 인입)이 키 인터록으로 동시투입 금지. ACB-201은 평상시 N.O(예비)이므로 실질적으로 TIE가 상시 이 경로를 백업 중인 것으로 판단.'),
  ('30000000-0000-0000-0000-000000000619', '30000000-0000-0000-0000-00000000060c', '조작주의(정전확산위험)', 'LC-101 Incoming PT(PTx2)는 ACB-101의 변압기측(MTR-01측)에 위치 — ACB-101만 개방해도 VCB-102(1차측)가 투입 상태면 변압기 2차측 전압이 PT에 남아있을 수 있음. Incoming PT 작업 전 VCB-102 실제 투입/개방 상태를 반드시 확인할 것.'),
  ('30000000-0000-0000-0000-00000000061b', '30000000-0000-0000-0000-00000000060d', '조작주의(정전확산위험)', 'LC-201 Incoming PT(PTx2)는 ACB-201의 변압기측(MTR-02측)에 위치 — ACB-201만 개방해도 VCB-202(1차측)가 투입 상태면 변압기 2차측 전압이 PT에 남아있을 수 있음. Incoming PT 작업 전 VCB-202 실제 투입/개방 상태를 반드시 확인할 것.');
